function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 20 || arr.length > 1000) return 'arr needs 20 to 1000 values.';
  if (arr.length % 20 !== 0) return 'The length of arr must be a multiple of 20.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 100000)) return 'Each value is an integer from 0 to 100000.';
  return null;
}

