function trimMean(arr) {
  arr.sort((a, b) => a - b);
  const cut = arr.length / 20;
  let total = 0;
  for (let i = cut; i < arr.length - cut; i++) {
    total += arr[i];
  }
  return total / (arr.length - 2 * cut);
}

