function trimMean(arr) {
  const rest = arr.slice();
  const drop = rest.length / 20;
  for (let k = 0; k < drop; k++) {
    rest.splice(rest.indexOf(Math.min(...rest)), 1);
    rest.splice(rest.indexOf(Math.max(...rest)), 1);
  }
  return rest.reduce((s, v) => s + v, 0) / rest.length;
}

