function generate(rand, size) {
  const n = size === 'large' ? 1000 : 20 * (1 + Math.floor(rand() * 3));
  const caps = [3, 10, 1000, 100000];
  const cap = size === 'large' ? 100000 : caps[Math.floor(rand() * caps.length)];
  const arr = Array.from({ length: n }, () => Math.floor(rand() * (cap + 1)));
  // Sprinkle a few extreme values so the trimmed ends matter.
  const spikes = Math.floor(rand() * 4);
  for (let k = 0; k < spikes; k++) arr[Math.floor(rand() * n)] = rand() < 0.5 ? 0 : 100000;
  return [arr];
}
